ST.xhtml:p:
R_Trriger1(CLK := g_biFixedLenHomeOpen OR bFixedLenHomeOpen);
R_Trriger2(CLK := g_biFixedLenHomeClose);

IF R_Trriger1.Q THEN
  g_boFixedLenHomeDone := FALSE;
  bHomeDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trriger2.Q THEN
  g_boFixedLenHomeDone := FALSE;
END_IF;


CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  FixedLenHome.Execute := TRUE;
  FixedLenHome.HomingMode := nHomeMode;
  FixedLenHome.Position := 0.0;
  FixedLenHome.bCalibrationCam := g_bFixedLenNegLimit;

  IF FixedLenHome.Done THEN
    FixedLenHome.Execute := FALSE;
    g_boFixedLenHomeDone := TRUE;
    bHomeDone := TRUE;
    nSwitchState := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 10;
  END_IF;
  IF FixedLenHome.CommandAborted OR FixedLenHome.Error THEN
    g_boFixedLenHomeDone := FALSE;
    FixedLenHome.Execute := FALSE;
    g_noerrorid := FixedLenHome.errorid;
    nSwitchState := 0;
  END_IF;
  10:
  FixedLenHome.Execute := FALSE;
  FixedLen_Stop.Execute := TRUE;
  IF FixedLen_Stop.Done AND g_bPlcStartBuffer THEN
    FixedLen_Stop.Execute := FALSE;
    nSwitchState := 1;
  END_IF;

  IF FixedLen_Stop.CommandAborted OR FixedLen_Stop.Error THEN
    FixedLen_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  FixedLenHome.Execute := FALSE;
  FixedLen_Stop.Execute := FALSE;
  g_boFixedLenHomeDone := FALSE;
  bHomeDone := TRUE;
  nSwitchState := 0;
END_IF;
